import{_ as n,o as e,c as a,a5 as i}from"./chunks/framework.CsGesDJn.js";const u=JSON.parse('{"title":"Hợp đồng Task Detail / Assignment / Comments","description":"","frontmatter":{},"headers":[],"relativePath":"feature/content-task-workflow/task-workflow-contract.md","filePath":"feature/content-task-workflow/task-workflow-contract.md"}'),o={name:"feature/content-task-workflow/task-workflow-contract.md"};function c(r,t,h,s,d,l){return e(),a("div",null,[...t[0]||(t[0]=[i('<h1 id="hop-đong-task-detail-assignment-comments" tabindex="-1">Hợp đồng Task Detail / Assignment / Comments <a class="header-anchor" href="#hop-đong-task-detail-assignment-comments" aria-label="Permalink to &quot;Hợp đồng Task Detail / Assignment / Comments&quot;">​</a></h1><p>&gt; <strong>Amendment 2026-10-18:</strong> Approval hiện hành ở <a href="./3-6-9-approval-sequence-creator-manager-client/spec.html">FR 3.6.9 v3</a> và <a href="./3-6-9-approval-sequence-creator-manager-client/plan.html">API/data plan</a>. Không QC; Manager→Client tùy chọn, năm trạng thái, một bản Post qua /editor, không review snapshot. Creator chỉ withdraw trước Manager decision; reject/withdraw không mở khóa brief/assignment. Các bảng/API có QC/plannedPublishAt/ASSIGNED bên dưới là contract lịch sử; FR3.6.1/2 hiện hành theo <a href="./task-structure-simplification/spec.html">Task structure</a>. Comments đã có code theo <a href="./task-comments-implementation-2026-10-17.html">bàn giao 17/10</a>, chưa đồng nghĩa mọi test live đã pass. Giai đoạn 1 Approval chỉ tài liệu, không API runtime hoặc DB APPLY.</p><p>&gt; <strong>Ưu tiên BA mới 2026-10-15:</strong> xem <a href="./task-five-state-inline-edit/spec.html">Task năm trạng thái + inline autosave</a>. TODO thay BACKLOG/DETAIL_IDENTIFIED/ASSIGNED; giao việc cần mô tả + deadline hợp lệ, không chuyển trạng thái. IN_REVIEW lưu bước QC/Manager/Client riêng, reject về IN_PROGRESS, bước cuối thành công mới FINISHED. Manager khóa sửa/giao lại sau lần bắt đầu đầu tiên. Phần vòng đời/form cũ bên dưới được giữ làm lịch sử, không phải contract mới. Đợt này chỉ code FR 3.6.1/2; Approval và Comments không được coi là đã hoàn thành.</p><p>Ngày 2026-10-14. DA-978 (FR 3.6.1/2), DA-1236 (FR 3.6.3). Nguồn BA: <a href="./task-detail-assignment-comments-roadmap.html">roadmap, quyết định Q13 mới nhất</a>. Nguồn thiết kế giai đoạn 1. Đợt 2026-10-15 đã code các workflow endpoints đọc/detail/assign/start và notification giao việc; comments/uploads vẫn là contract mục tiêu. Không thay editor hoặc Approval của thành viên khác. Bằng chứng và giới hạn ở <a href="./task-workflow-phase-2-3.html">bàn giao đợt 2/3</a>.</p><h2 id="_1-ranh-gioi-du-lieu-va-quyen" tabindex="-1">1. Ranh giới dữ liệu và quyền <a class="header-anchor" href="#_1-ranh-gioi-du-lieu-va-quyen" aria-label="Permalink to &quot;1. Ranh giới dữ liệu và quyền&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Dữ liệu/hành động</th><th>Manager thực tế trong WS</th><th>Creator active trong WS</th><th>Client active trong WS</th></tr></thead><tbody><tr><td>Đọc workflow, bình luận, xem ảnh ATTACHED</td><td>Có</td><td>Có</td><td>Mọi Task cùng Workspace</td></tr><tr><td>Sửa brief/deadline</td><td>Trước lần bắt đầu đầu tiên</td><td>Không</td><td>Không</td></tr><tr><td>Giao Creator/QC</td><td>Sau DETAIL_IDENTIFIED, trước lần bắt đầu</td><td>Không</td><td>Không</td></tr><tr><td>Bắt đầu làm</td><td>Không thay Creator</td><td>Chỉ assignee, ASSIGNED, lần đầu</td><td>Không</td></tr><tr><td>Bình luận Task COMPLETED/CANCELLED</td><td>Có</td><td>Có</td><td>Có, nếu vẫn active cùng Workspace</td></tr><tr><td>Editor/content/submit/approval</td><td>Giữ contract của module hiện có; không suy ra quyền từ bảng này</td><td></td><td></td></tr></tbody></table><p>Owner cấp Agency không tự có quyền Manager trong WS. Owner có membership Manager thì dùng quyền Manager. Resolve ClientProfile → User ID, không nhầm ID membership/profile thành assignee/mention userId. Mọi truy cập đều scope workspaceId + taskId, xác minh membership active của đúng WS. <strong>Q13 confirmed 2026-10-14:</strong> Client được xem/bình luận mọi Task cùng Workspace, kể cả Task Manager tạo thủ công, Task cũ, lịch sử bình luận và ảnh ATTACHED. Không phân biệt nội bộ/thường, không có field/filter/bộ chọn visibility. Q13 thay thế phần phân quyền Q6/Q9 và ràng buộc Q12 trước đây. <code>requiresClientApproval</code> chỉ quyết định bước Client duyệt kết quả; true/false không đổi quyền đọc/bình luận. Không cấp quyền editor/content/assign cho Client hoặc quyền xem cho người ngoài/đã rời Workspace. DRAFT upload vẫn chỉ chủ upload được preview. Client chỉ nhận notification comment khi được mention (Q11 giữ nguyên). Thiếu revision/start marker ở legacy chỉ ảnh hưởng mutation quản lý, không chặn đọc/bình luận.</p><h2 id="_2-schema-bo-sung-khong-thay-identity" tabindex="-1">2. Schema bổ sung, không thay identity <a class="header-anchor" href="#_2-schema-bo-sung-khong-thay-identity" aria-label="Permalink to &quot;2. Schema bổ sung, không thay identity&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Collection</th><th>Bổ sung / mục đích</th></tr></thead><tbody><tr><td>tasks</td><td>workflowRevision; plannedPublishAt; inputReferences; detailIdentifiedAt/By; assignedAt/By; firstStartedAt/By</td></tr><tr><td>task_comments</td><td>Bình luận append-only, snapshot tác giả, mention User IDs, attachment IDs, clientRequestId</td></tr><tr><td>task_comment_uploads</td><td>Ảnh riêng tư của Task, chủ upload, MIME/byteSize, storageKey, trạng thái gắn comment/cleanup</td></tr><tr><td>task_notification_outbox</td><td>Sự kiện gửi từng người, eventKey chống trùng, lease/retry; worker đưa vào inbox SQL hiện có</td></tr></tbody></table><p>Field mới của <code>tasks</code> <strong>optional trong validator</strong>, không thêm required và không sửa documents cũ. Writer mới phải khởi tạo workflowRevision=0, firstStartedAt/By=null, giữ source metadata để truy vết, không phân quyền theo nguồn. Spring Data có thể bỏ field null khi serialize: phải dùng <code>@Field(write = ALWAYS)</code> hoặc targeted insert bảo đảm marker null thực sự được ghi; test kiểm tra BSON field presence, không chỉ Java DTO. Thiếu firstStartedAt ở legacy là <strong>chưa biết lịch sử</strong>, không đồng nghĩa chưa bắt đầu; inventory/reconcile tường minh trước cho sửa/giao lại. Không mở khóa chỉ vì status=ASSIGNED. Migration chỉ mở rộng schema, không bật workflow hay ACL ở ứng dụng.</p><p>Giữ nguyên Task ID, type, sourceType/sourceRefId, campaignId/campaignWorkItemId, typeMetadata, approvalRound, cancellation và task_approvals. Campaign sourceRefId hiện là <strong>workItem ID</strong>; Content Request sourceRefId là Request ID. Mốc Campaign không phải Task. Đầu việc bổ sung không thay sản lượng/kế hoạch đã duyệt.</p><p>Giới hạn kỹ thuật dự kiến (không phải BA mới): description 10.000 ký tự ở API; tối đa 20 reference HTTP(S), label 200/url 2.048; comment plain text 1..10.000 ký tự; tên file 255; cursor opaque, limit mặc định 30/tối đa 100. Không đặt giới hạn mới lên description legacy ở DB. Ảnh theo BA: tối đa 5 JPEG/PNG/WebP, mỗi ảnh 5 MB = 5×1024×1024 byte.</p><h2 id="_3-api-workflow-contract-muc-tieu" tabindex="-1">3. API workflow (contract mục tiêu) <a class="header-anchor" href="#_3-api-workflow-contract-muc-tieu" aria-label="Permalink to &quot;3. API workflow (contract mục tiêu)&quot;">​</a></h2><p>Prefix <code>/api/v1/workspaces/{workspaceId}/tasks</code>:</p><table tabindex="0"><thead><tr><th>Method / suffix</th><th>Input chính</th><th>Output <code>data</code></th></tr></thead><tbody><tr><td>GET <code>/{taskId}/workflow</code></td><td>—</td><td>Workflow DTO và allowedActions</td></tr><tr><td>GET prefix hiện có (không suffix)</td><td>page, size, sort, status, type, search, campaignId</td><td>Spring Page; reuse DA-979, không thêm list <code>/workflow</code></td></tr><tr><td>GET <code>/{taskId}/member-options</code></td><td>purpose=ASSIGNMENT hoặc MENTION</td><td>User ID, displayName, role hợp lệ</td></tr><tr><td>PATCH <code>/{taskId}/detail</code></td><td>description, dueDate, plannedPublishAt?, inputReferences, expectedRevision</td><td>Workflow DTO mới</td></tr><tr><td>POST <code>/{taskId}/assign</code></td><td>assigneeId, qcAssigneeId=null hoặc UUID, requiresClientApproval, expectedRevision</td><td>Workflow DTO ASSIGNED</td></tr><tr><td>POST <code>/{taskId}/start</code></td><td>expectedRevision</td><td>Workflow DTO IN_PROGRESS</td></tr></tbody></table><p>Đợt 2026-10-15 reuse list đã nối dữ liệu thật của DA-979; không thêm list <code>/workflow</code> hoặc Calendar/Kanban thứ hai. member-options hiện chỉ phục vụ ASSIGNMENT và chỉ Manager, chưa triển khai MENTION. Đặt route tĩnh tránh va chạm <code>/{taskId}</code> hiện tại. Editor TaskResponse giữ nguyên; không mở Client vào endpoints content/Yjs/versions để đọc workflow.</p><p>Workflow DTO: id/workspaceId/type/name/status/source/campaign IDs, description, dueDate, plannedPublishAt, inputReferences, assignee/QC, requiresClientApproval, workflowRevision, firstStartedAt, allowedActions và trạng thái <code>legacyReviewRequired</code> khi thiếu dữ liệu an toàn. Không trả storageKey hoặc nội dung typeMetadata chuyên biệt qua DTO chung.</p><p><code>expectedRevision</code> nguyên không âm bắt buộc. Dùng UTC timestamp RFC3339 có offset; API so sánh thời gian theo timezone Workspace, không theo timezone trình duyệt. DueDate Campaign: từ đầu ngày max(today,start) đến hết ngày end; plannedPublishAt POST không trước dueDate và cùng khung Campaign. Manual không Campaign: từ đầu hôm nay. Ngày đăng POST là optional trong đợt này; bỏ trống không tự schedule. Không cho field này với loại khác.</p><p>HTTP lỗi dự kiến: 401 hết/mất phiên; 403 FORBIDDEN do role/membership; 404 TASK_NOT_FOUND cho task không thuộc scope (tránh tiết lộ tồn tại); 400 VALIDATION_ERROR/INVALID_ASSIGNEE/INVALID_QC_ASSIGNEE/QC_CANNOT_BE_SAME_AS_ASSIGNEE; 409 TASK_REVISION_CONFLICT/TASK_DETAIL_NOT_IDENTIFIED/TASK_WORKFLOW_LOCKED/ TASK_START_HISTORY_UNVERIFIED/CAMPAIGN_COMPLETED; 503 TASK_SCHEMA_NOT_READY. Luôn dùng error envelope hiện có + field errors; UI giữ input, không tự retry mutation cũ khi 409.</p><h2 id="_4-concurrency-va-lifecycle-tich-hop" tabindex="-1">4. Concurrency và lifecycle tích hợp <a class="header-anchor" href="#_4-concurrency-va-lifecycle-tich-hop" aria-label="Permalink to &quot;4. Concurrency và lifecycle tích hợp&quot;">​</a></h2><ol><li>Auth/member → Task scope → schema readiness → đọc revision/status và metadata. Legacy/start guards chỉ chặn mutation quản lý, không chặn Client đọc/bình luận Task cùng WS.</li><li>Mutation Task gắn Campaign dùng cùng SQL agreement lock với CampaignClosureService.</li><li>Validate toàn payload + membership assignee/QC hiện tại. Targeted <code>$set/$inc</code>, CAS theo revision + status + first-start guard; không save/replace document từ DTO.</li><li>Giữ updatedAt tương thích writer cancellation. Các writer cùng sửa trạng thái phải phối hợp revision; trước khi đủ phối hợp dùng thêm điều kiện updatedAt và không tuyên bố mọi writer đã CAS an toàn.</li><li>Task mutation/comment + outbox trong <strong>cùng Mongo transaction</strong>. Không gọi SQL inbox như thể PostgreSQL và Mongo cùng transaction ACID. Không tạo Task/notification nửa chừng.</li><li>Start đầu tiên: chỉ assignee active bấm, ASSIGNED → IN_PROGRESS, ghi firstStartedAt/By một lần. Reject về ASSIGNED vẫn giữ marker. Resubmit/review thuộc E51-03; chưa sửa module đó ở đây.</li><li>E51-03 phải duyệt lại QC (nếu có) trên nội dung mới sau reject, giữ lịch sử approval cũ. Việc quay lại IN_PROGRESS/submit sau reject cần cùng chủ Approval tích hợp, không reset marker.</li></ol><p>Campaign completed không sửa/giao/bắt đầu Task gắn Campaign; comments vẫn cho phép theo BA. Cancel mọi trạng thái chưa terminal giữ audit; workflow không phục hồi CANCELLED. Membership có thể thay đổi ngoài Mongo: kiểm tra lại trước commit/delivery/download và không cache quyền dài hạn; không hứa cross-store atomicity. Cần test race removal ở giai đoạn tích hợp.</p><h2 id="_5-api-comments-va-file-rieng-tu" tabindex="-1">5. API comments và file riêng tư <a class="header-anchor" href="#_5-api-comments-va-file-rieng-tu" aria-label="Permalink to &quot;5. API comments và file riêng tư&quot;">​</a></h2><p>Prefix <code>.../tasks/{taskId}</code>:</p><ul><li>GET <code>/comments?cursor=&amp;limit=30</code> → 200 <code>{items,nextCursor}</code> theo createdAt DESC + id DESC; UI đảo thứ tự để đọc timeline, không làm mất/trùng khi timestamp bằng nhau.</li><li>POST <code>/comments</code> → 201 <code>{id,taskId,authorId,authorDisplayName,authorRole,content,mentions,attachmentIds,createdAt}</code>. Payload <code>{content,mentions:[],attachmentIds:[],clientRequestId:UUID}</code>; không nhận authorId/role từ Client. Retry cùng tác giả/task/clientRequestId và cùng payload trả comment đã tạo; cùng key khác payload → 409.</li><li>POST <code>/comment-uploads</code> multipart <code>file</code> → 201 <code>{id,name,contentType,byteSize}</code>.</li><li>GET <code>/comment-uploads/{uploadId}/content</code> → stream ảnh qua API đã auth sau kiểm tra ACL; không lộ public S3 URL/key và không dùng MailAttachment/Material Library làm endpoint chung.</li></ul><p>Kiểm tra MIME thật, kích thước và decode ảnh; không chỉ tin extension/content-type từ browser. Bind upload cùng Task/WS/chủ gửi đúng một comment, tối đa 5, bằng CAS trong transaction; không nhận URL arbitrary, không cho bind lại upload ATTACHED. Người có quyền Task mới đọc được ảnh ATTACHED; DRAFT chỉ chủ upload được preview. Plain text, link HTTP(S) an toàn, không render HTML tùy ý.</p><p>Upload metadata có expiresAt cho DRAFT; cleanup worker lấy lease/chuyển CLEANUP_PENDING, xóa object thành công rồi mới xóa metadata. <strong>Không TTL</strong>: TTL metadata có thể làm mất dấu object rác. Cleanup và bind CAS state để không xóa ảnh đã gắn. Thời gian lưu DRAFT là cấu hình kỹ thuật cần ghi setup, không tự đặt thành BA hay xóa shared data trong phase 1.</p><h2 id="_6-notification" tabindex="-1">6. Notification <a class="header-anchor" href="#_6-notification" aria-label="Permalink to &quot;6. Notification&quot;">​</a></h2><p>TASK_ASSIGNED gửi Creator mới nhận việc; TASK_COMMENTED lấy hợp của mentions + Creator phụ trách + Managers. BA mới không còn QC/review chéo: không gửi cho người QC lịch sử. Owner cần membership Manager trong Workspace. Dedup/exclude author; Client chỉ khi được mention; recheck ACL trước delivery. Không gửi email. Mỗi delivery có eventKey ổn định và UUID id dùng cho SQL <code>user_notifications.id</code>. Worker lease + retry; INSERT ON CONFLICT chống trùng, đánh SENT chỉ sau SQL commit. Nếu người nhận mất quyền → SUPPRESSED; lỗi tạm thời retry, log chỉ IDs/code, không log comment/token. Không payload nội dung bình luận nhạy cảm vào notification; link Task Detail kiểm tra ACL lại khi mở. SQL inbox đã đủ cột, <strong>không có migration PostgreSQL mới cho ba FR này</strong>.</p><h2 id="_7-pham-vi-va-checkpoint-phoi-hop" tabindex="-1">7. Phạm vi và checkpoint phối hợp <a class="header-anchor" href="#_7-pham-vi-va-checkpoint-phoi-hop" aria-label="Permalink to &quot;7. Phạm vi và checkpoint phối hợp&quot;">​</a></h2><ul><li>Business dự kiến TaskWorkflowController/Service/Access/Store/DTO, TaskCommentService/UploadService, TaskNotificationOutboxWorker; reuse WorkspaceAccessService và FileStorageService ở mức adapter.</li><li>Web module Tasks riêng; locale <code>src/locales/{vi,en}/tasks.json</code> (xác minh registry i18n trước code), route detail và link Campaign/Request. Không thay UI Chat/Mail/editor/Calendar của người khác.</li><li>Gateway route API hiện có; chỉ sửa nếu test chứng minh thiếu route, không chỉnh global auth.</li><li>Infrastructure migration + init + checker + tests; không chạy init lên Atlas, không backfill.</li><li>Chủ E51-03 (Phước): marker/start/CAS/resubmit. Chủ E51-05 (Phước): list/entry point. Chủ editor/Livestream/Survey: không đổi identity/content contract. Chưa tuyên bố đã được họ review.</li><li>Phase 1 chỉ schema/tài liệu/offline tests. Chỉ chuyển phase ứng dụng sau review hợp đồng tích hợp.</li></ul>',31)])])}const m=n(o,[["render",c]]);export{u as __pageData,m as default};
